    x = r.random()
    if x < 0.45:
        s = r.randint(0, 30); ops.append(('book', s, s + r.randint(-1, 8))); starts.append(s)
    elif x < 0.6: ops.append(('cancel', r.choice(starts) if starts and r.random() < 0.8 else r.randint(0, 30)))
    elif x < 0.85: ops.append(('first_fit', r.randint(0, 30), r.randint(1, 6)))
    else:
        a = r.randint(0, 30); ops.append(('free_between', a, a + r.randint(-3, 30 // 3)))
result = sol.run_ops(ops)

